def git(repo: Path, *args: str) -> None:
    subprocess.run(["git", "-C", str(repo), *args], check=True,
                   capture_output=True, text=True)


def make_repo(tmp_path: Path) -> Path:
    """A real git repo with one commit; returns repo root."""
    repo = tmp_path / "repo"
    repo.mkdir()
    git(repo, "init", "-q", "-b", "main")
    git(repo, "config", "user.email", "t@example.invalid")
    git(repo, "config", "user.name", "t")
    (repo / "README.md").write_text("x\n")
    # The production tool requires its runtime stores and Assay artifacts to
    # stay out of the judged tree. Give ordinary fixtures the consumer setup;
    # tests for the missing-ignore refusal build their own explicit fixture.
    (repo / ".gitignore").write_text(".run-gate/\n.assay/\n")
    git(repo, "add", "README.md", ".gitignore")
    git(repo, "commit", "-q", "-m", "init")
    return repo


def commit_all(repo: Path, msg: str) -> None:
    git(repo, "add", "-A")
    git(repo, "commit", "-q", "-m", msg)


def make_worktree(repo: Path, tmp_path: Path, name: str = "w1") -> Path:
    worktree = tmp_path / name
    git(repo, "worktree", "add", "-q", "-b", name, str(worktree))
    return worktree


def _upgrade_fixture_environment_modes(config: str) -> str:
    """Fixture migration for the RG-78 parser's now-required ``mode`` key.

    Most historical tests exercise unrelated behavior and intentionally use
    the pre-RG-78 fixture shorthand. Upgrade those fixtures textually while
    preserving their TOML shape. RG-78's missing-mode oracle opts out.
    """
    lines = textwrap.dedent(config).strip("\n").splitlines()
    index = 0
    while index < len(lines):
        match = re.match(r"\s*\[environments\.([A-Za-z0-9_-]+)\]\s*$",
                         lines[index])
        if not match:
            index += 1
            continue
        end = index + 1
        while end < len(lines) and not re.match(r"\s*\[", lines[end]):
            end += 1
        section = lines[index + 1:end]
        if not any(re.match(r"\s*mode\s*=", line) for line in section):
            mode = "host" if match.group(1) == "bare-host" else "ephemeral"
            lines.insert(index + 1, f'mode = "{mode}"')
            end += 1
        index = end
    declared = set(re.findall(
        r"^\s*\[environments\.([A-Za-z0-9_-]+)\]\s*$",
        "\n".join(lines), re.MULTILINE))
    referenced = set(re.findall(r'^\s*environment\s*=\s*["\']([^"\']+)',
                                "\n".join(lines), re.MULTILINE))
    additions = []
    if "bare-host" in referenced and "bare-host" not in declared:
        additions += ["", "[environments.bare-host]", 'mode = "host"']
    if "host" in referenced and "host" not in declared:
        additions += ["", "[environments.host]", 'mode = "ephemeral"',
                      f'image = {json.dumps(run_gate.DEFAULT_HOST_IMAGE)}']
    return "\n".join(lines + additions) + "\n"


def make_project(repo: Path, config: str, name: str = "proj", *,
                 upgrade_modes: bool = True) -> Path:
    """Project subdir with a committed run-gate.toml; returns project dir."""
    proj = repo / name
    proj.mkdir()
    if upgrade_modes:
        config = _upgrade_fixture_environment_modes(config)
        central_path = repo / run_gate.ROOT_CONFIG_NAME
        if central_path.is_file():
            central_path.write_text(_upgrade_fixture_environment_modes(
                central_path.read_text()))
    (proj / "run-gate.toml").write_text(textwrap.dedent(config))
    commit_all(repo, f"lane config {name}")
    return proj


# RG-55: `docker exec <daemon> cgprofile ctl <verb> ... --json` is answered
# from per-test plan files under
# $RUN_GATE_TEST_CGPROFILE_PLAN/<verb>.{json,exit,sleep} (set_cgprofile_plan
# writes them); unset (every pre-RG-55 test) is a silent no-op, matching the
# prior behavior of an unmatched `exec` falling straight through to the
# shim's own `exit 0`. Shared by fake_docker's `exec)` case; embedded once
# here so future shims (fake_docker_executing's own `exec)` branch, when a
# later package wires ProfilerClient calls alongside a real lane exec) can
# reuse the identical snippet instead of drifting apart.
CGPROFILE_SHIM_CASE = """\
            if [ -n "$RUN_GATE_TEST_CGPROFILE_PLAN" ] && [ "$3" = "cgprofile" ] && [ "$4" = "ctl" ]; then
              verb="$5"
              plan="$RUN_GATE_TEST_CGPROFILE_PLAN/$verb"
              if [ -f "$plan.sleep" ]; then sleep "$(cat "$plan.sleep")"; fi
              if [ -f "$plan.json" ]; then cat "$plan.json"; fi
              if [ -f "$plan.exit" ]; then exit "$(cat "$plan.exit")"; fi
            fi"""


def set_cgprofile_plan(tmp_path: Path, monkeypatch, **verbs) -> Path:
    """Configure fake_docker's `cgprofile ctl <verb>` responses. Each kwarg
    is `<verb>=(stdout_text_or_None, exit_code_or_None, sleep_seconds_or_None)`."""
    plan_dir = tmp_path / "cgprofile-plan"
    plan_dir.mkdir(exist_ok=True)
    for verb, (stdout, exit_code, sleep_s) in verbs.items():
        if stdout is not None:
            (plan_dir / f"{verb}.json").write_text(stdout)
        if exit_code is not None:
            (plan_dir / f"{verb}.exit").write_text(str(exit_code))
        if sleep_s is not None:
            (plan_dir / f"{verb}.sleep").write_text(str(sleep_s))
    monkeypatch.setenv("RUN_GATE_TEST_CGPROFILE_PLAN", str(plan_dir))
    return plan_dir


def fake_docker(tmp_path: Path, monkeypatch, wait_code: int | str = 0) -> Path:
    """PATH-shim docker that RECORDS every invocation losslessly (args joined
    with \\037 = \\x1f — plain `echo "$@"` destroys quoting; \\xHH is NOT
    portable printf, octal is)."""
    shim_dir = tmp_path / "shim"
    shim_dir.mkdir(exist_ok=True)
    _TEST_OWNED_SHIM_DIRS.add(str(shim_dir))
    log = tmp_path / "docker-calls.log"
    log.write_text("")
    verdict_helper = tmp_path / "fake-assay-verdict.py"
    verdict_helper.write_text(textwrap.dedent("""\
        import json
        from pathlib import Path
        import re
        import shlex
        import subprocess
        import sys

        status = sys.argv[1]
        for argument in sys.argv[2:]:
            marker = "--verdict-json "
            if marker not in argument:
                continue
            value = argument.split(marker, 1)[1].strip().split()[0]
            path = Path(value.strip("'\\\""))
            base = Path.cwd()
            if not path.is_absolute():
                # Assay writes after run-gate's inner command has changed to
                # the project directory. The fake Docker process itself runs
                # from the pytest checkout, so mirror that explicit `cd`.
                changedir = re.search(
                    r"(?:^|&&)\\s*cd\\s+(.+?)(?=\\s*&&|\\s*;|$)",
                    argument)
                if changedir:
                    parts = shlex.split(changedir.group(1))
                    if parts:
                        candidate = Path(parts[0])
                        base = candidate if candidate.is_absolute() else base / candidate
                path = base / path
            path.parent.mkdir(parents=True, exist_ok=True)
            commit_result = subprocess.run(
                ["git", "-C", str(base), "rev-parse", "--verify", "HEAD"],
                capture_output=True, text=True)
            commit = commit_result.stdout.strip() \
                if commit_result.returncode == 0 else ""
            exit_code = int(status)
            outcome = {
                0: "PASS", 1: "FAIL", 2: "ERROR", 3: "NO_MEASUREMENT",
                4: "BUDGET_EXCEEDED", 5: "INCONCLUSIVE",
            }.get(exit_code, "ERROR")
            path.write_text(json.dumps({
                "outcome": outcome,
                "exit_code": exit_code,
                "assay_version": "7.2.0",
                "commit": commit,
                "reason_code": None,
                "judge_provenance": {
                    "name": "assay", "version": "7.2.0",
                    "artifact": "test-assay", "digest_algorithm": "sha256",
                    "digest": "a" * 64,
                },
            }))
    """))
    helper_command = shlex.quote(str(verdict_helper))
    inventory_helper = tmp_path / "fake-assay-inventory.py"
    inventory_helper.write_text(textwrap.dedent("""\
        import json
        import shlex
        import sys
        import tomllib
        from pathlib import Path

        script = sys.argv[1]
        first = script.split("&&", 1)[0]
        command = shlex.split(first)
        project = (Path(command[1]) if len(command) > 1
                   and command[0] == "cd" else Path.cwd())
        documents = [project / "run-gate.toml"]
        documents.extend(parent / "run-gate.root.toml"
                         for parent in project.parents)
        names = set()
        for path in documents:
            try:
                config = tomllib.loads(path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, tomllib.TOMLDecodeError):
                continue
            lanes = config.get("lanes", {})
            if isinstance(lanes, dict):
                for lane in lanes.values():
                    if isinstance(lane, dict) and lane.get("kind") == "assay":
                        name = lane.get("assay_lane")
                        if isinstance(name, str):
                            names.add(name)
                    elif isinstance(lane, dict) and lane.get("kind") == "sequence":
                        names.update(member for member in lane.get("lanes", [])
                                     if isinstance(member, str)
                                     and member not in lanes)
            assay = config.get("assay", {})
            imported = assay.get("import", {}) if isinstance(assay, dict) else {}
            imported_names = imported.get("lanes") if isinstance(imported, dict) else None
            if isinstance(imported_names, list):
                names.update(name for name in imported_names
                             if isinstance(name, str))
        entries = [
            {"name": name, "rigor": ["R0"], "base_source": None,
             "external_tools": [], "argv0": None, "language": None}
            for name in sorted(names)
        ]
        print(json.dumps({"assay_version": "9.0.0",
                          "inventory_schema": 1, "lanes": entries}))
    """))
    inventory_helper_command = shlex.quote(str(inventory_helper))
    shim = shim_dir / "docker"
    shim.write_text(textwrap.dedent(f"""\
        #!/bin/sh
        printf '%s\\037' "$@" >> "{log}"
        printf '\\n' >> "{log}"
        case "$1" in
          run)
            case "$*" in
              *RUN_GATE_STATE_ROOT_READY*)
                echo "RUN_GATE_STATE_ROOT_READY"
                ;;
              *"lanes --json"*)
                for last; do :; done
                first_path="${{PATH%%:*}}"
                if [ -x "$first_path/assay" ]; then
                  exec bash -c "$last"
                fi
                python3 {inventory_helper_command} "$last"
                ;;
              *)
                python3 {helper_command} "{wait_code}" "$@"
                echo "fake-container-id"
                ;;
            esac
            ;;
          logs) echo "FAKE-LOGS-LINE" ;;
          wait) printf '%s\\n' "{wait_code}" ;;
          rm) : ;;
          exec)
            case "$*" in
              *RUN_GATE_STATE_ROOT_READY*)
                echo "RUN_GATE_STATE_ROOT_READY"
                ;;
              *"lanes --json"*)
                for last; do :; done
                first_path="${{PATH%%:*}}"
                if [ -x "$first_path/assay" ]; then
                  exec bash -c "$last"
                fi
                python3 {inventory_helper_command} "$last"
                ;;
              *)
                python3 {helper_command} "{wait_code}" "$@"
                {CGPROFILE_SHIM_CASE}
                ;;
            esac
            ;;
        esac
        exit 0
    """))
    shim.chmod(shim.stat().st_mode | stat.S_IEXEC)
    monkeypatch.setenv("PATH", f"{shim_dir}:{os.environ['PATH']}")
    return log


def fake_docker_executing(tmp_path, monkeypatch) -> Path:
    """A docker shim that RECORDS like fake_docker but also EXECUTES the
    inner `bash -c <script>` on the host for `run`/`exec`.

    RG-25/RG-26 probes are only meaningful if the script actually runs: the
    fitness check's whole content is `command -v` inside the environment, and
    the inventory's is a real `assay lanes --json`. A shim that echoed canned
    output would pin construction, not acceptance — the exact substitute-
    interpreter failure class this project exists to kill (README "an argv
    proves construction, not acceptance").

    State-root probes are answered READY by default: this fake represents a
    healthy lane environment. RG-49's unavailable-root oracles use explicit
    probe responses so they can test the refusal boundary directly.
    """
    log = fake_docker(tmp_path, monkeypatch)
    shim = shim_dir_of(monkeypatch) / "docker"
    verdict_helper = shlex.quote(str(Path(tmp_path) / "fake-assay-verdict.py"))
    shim.write_text(textwrap.dedent(f"""\
        #!/bin/sh
        printf '%s\\037' "$@" >> "{log}"
        printf '\\n' >> "{log}"
        case "$1" in
          run)
            # `-d` is the JUDGED lane (detached, R-15) — recorded, not run.
            # Anything else is an RG-25/RG-26 probe (`--rm`): really execute.
            case "$2" in
              -d)
                python3 {verdict_helper} "0" "$@"
                echo "fake-container-id"
                ;;
              *) for last; do :; done
                 case "$last" in
                   *RUN_GATE_STATE_ROOT_READY*) echo "RUN_GATE_STATE_ROOT_READY" ;;
                   *) exec bash -c "$last" ;;
                 esac
                 ;;
            esac
            ;;
          exec)
            for last; do :; done
            case "$last" in
              *--verdict-json*)
                python3 {verdict_helper} "0" "$@"
                exit 0
                ;;
              *) case "$last" in
                   *RUN_GATE_STATE_ROOT_READY*) echo "RUN_GATE_STATE_ROOT_READY" ;;
                   *) exec bash -c "$last" ;;
                 esac
                 ;;
            esac
            ;;
          logs) echo "FAKE-LOGS-LINE" ;;
          wait) printf '0\\n' ;;
          rm) : ;;
          ps) printf 'probe-runner\\n' ;;
        esac
        exit 0
    """))
    shim.chmod(shim.stat().st_mode | stat.S_IEXEC)
    return log


def install_fake_assay(monkeypatch, body: str, name: str = "assay") -> Path:
    """A PATH-shim Assay executable with a real-shaped verdict artifact.

    Inventory probes still return the exact test-provided output. For a run,
    the wrapper preserves the fake command's status and writes the verdict
    artifact run-gate now requires, just as a real judge does.
    """
    path = shim_dir_of(monkeypatch) / name
    original = textwrap.dedent(body)
    if original.startswith("#!/"):
        original = original.split("\n", 1)[1]
    real = path.with_name(path.name + ".real")
    real.write_text("#!/bin/sh\n" + original)
    real.chmod(real.stat().st_mode | stat.S_IEXEC)
    path.write_text(textwrap.dedent("""\
        #!/bin/sh
        if [ "$1" != "run" ]; then exec "$0.real" "$@"; fi
        "$0.real" "$@"
        result=$?
        previous=""
        verdict=""
        for argument in "$@"; do
          if [ "$previous" = "--verdict-json" ]; then verdict="$argument"; break; fi
          previous="$argument"
        done
        if [ -n "$verdict" ]; then
          mkdir -p "$(dirname "$verdict")"
          case "$result" in
            0) outcome=PASS ;;
            1) outcome=FAIL ;;
            2) outcome=ERROR ;;
            3) outcome=NO_MEASUREMENT ;;
            4) outcome=BUDGET_EXCEEDED ;;
            5) outcome=INCONCLUSIVE ;;
            *) outcome=ERROR ;;
          esac
          printf '{"outcome":"%s","exit_code":%s,"reason_code":null,"judge_provenance":{"name":"assay","version":"7.2.0","artifact":"test-assay","digest_algorithm":"sha256","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}\\n' \\
            "$outcome" "$result" > "$verdict"
        fi
        exit "$result"
    """))
    path.chmod(path.stat().st_mode | stat.S_IEXEC)
    return path


def docker_runs(log: Path) -> list[list[str]]:
    out = []
    for line in log.read_text().splitlines():
        parts = line.split("\x1f")
        if parts and parts[0] == "run":
            out.append([p for p in parts if p != ""])
    return out


def docker_execs(log: Path) -> list[list[str]]:
    out = []
    for line in log.read_text().splitlines():
        parts = line.split("\x1f")
        if parts and parts[0] == "exec":
            out.append([p for p in parts if p != ""])
    return out


def lane_runs(log: Path) -> list[list[str]]:
    """Only the JUDGED container runs. Since RG-26 an assay lane also issues a
    read-only `assay lanes --json` probe (`docker run --rm`), so index 0 of
    docker_runs() is no longer necessarily the lane — the detached form is
    what identifies it (R-15)."""
    return [call for call in docker_runs(log) if "-d" in call]


def lane_execs(log: Path) -> list[list[str]]:
    """Only the JUDGED assay `docker exec`s — never its read-only probes."""
    return [call for call in docker_execs(log)
            if "--verdict-json" in call[-1]]


# Shim directories THIS suite created itself (fake_docker's `tmp_path/shim`).
# RG-87: only these may ever be written into; a pre-existing PATH directory
# (e.g. the developer's ~/.local/bin) is never a legal shim target.
_TEST_OWNED_SHIM_DIRS: set[str] = set()


def shim_dir_of(monkeypatch) -> Path:
    first = os.environ["PATH"].split(":")[0]
    if first and first in _TEST_OWNED_SHIM_DIRS:
        return Path(first)
    # RG-87: never write into a pre-existing PATH directory, writable or not
    # (the old "first writable PATH entry" rule replaced the developer's real
    # `assay` with a PASS-fabricating fake). Every shim goes to a private
    # per-test directory that is PREPENDED to PATH.
    private = Path(tempfile.mkdtemp(prefix="run-gate-test-bin-"))
    _TEST_OWNED_SHIM_DIRS.add(str(private))
    atexit.register(shutil.rmtree, private, ignore_errors=True)
    monkeypatch.setenv("PATH", f"{private}:{os.environ['PATH']}")
    return private


def _shared_lock_dir() -> Path:
    """RW-46a: `tests/conftest.py`'s `isolate_shared_lock_dir` autouse
    fixture points `RUN_GATE_LOCK_DIR` at a throwaway per-test directory —
    every test that pre-opens/probes a lock file by hand (the RG-20/R-41
    tests below) must construct that SAME path, never a hard-coded
    `/tmp`, or its manual "holder" fd and run-gate's own lock would sit on
    two different files and the test would stop proving anything. Reads
    the env var directly (not a cached module import) so it stays correct
    even if this file's own `run_gate` module object identity ever changes
    across a collection boundary (see the fixture's own docstring)."""
    return Path(os.environ["RUN_GATE_LOCK_DIR"])


