def test_budget_hard_limit_is_printed(tmp_path, monkeypatch, capsys):
    repo = make_repo(tmp_path)
    proj = make_project(repo, """\
        schema_version = 1
        [environments.tester-unified]
        image = "tester-unified:local"
        [lanes.suite]
        kind = "command"
        environment = "tester-unified"
        budget = "20m"
        argv = ["bash", "-c", "true"]
        clean_tree = false
    """)
    log = fake_docker(tmp_path, monkeypatch)
    monkeypatch.setattr(run_gate, "physical_path",
                        lambda p, **k: Path("/phys"))
    # in-process main() discovers the project from sys.argv[0] — pin it
    monkeypatch.chdir(proj)
    monkeypatch.setattr(sys, "argv", ['run-gate', 'suite'])
    code = run_gate.main(["suite"])
    out = capsys.readouterr().out
