def test_no_stdlib_violations():
    """Anti-goal: non-stdlib imports. Parse the import table."""
    src = _TOOL.read_text()
    imports = [l.split()[1].split(".")[0] for l in src.splitlines()
               if l.startswith("import ") or l.startswith("from ")]
    allowed = {"argparse", "os", "re", "shlex", "shutil", "subprocess", "sys",
               "time", "tomllib", "pathlib", "fcntl",  # fcntl: stdlib, Linux-only (RG-20 locks)
               "ast",   # ast: RG-23 helper-wrapped env reads in --check-env
               "json",  # json: RG-25 `assay lanes --json` inventory
               # calendar: RW-17 turns docker's RFC3339 stamps into a UTC
               # epoch (`calendar.timegm`) for a collected run's duration.
               # stdlib, and the only alternative was `datetime`, a bigger
               # import for the same one call.
               "calendar",
               # threading: RG-41's LogStreamWatch pumps a container command
               # lane's stdout on a background thread so the main poll loop
               # can ask, non-blockingly, how long it has been silent.
               "threading",
               "threading", "queue", "socket",
               # atexit + tempfile: RG-NARROW's per-run credential-free copy
               # of the git config is written to a private temp dir and
               # removed when the process exits.
               "atexit", "tempfile",
               # math: RG-55 ResourceAccumulator's nearest-rank percentile
               # (contract Sec 7's own ceil(p/100*N) formula, math.ceil).
               "math",
               # secrets: RG-55 profile-session tokens (contract Sec 4.1,
               # secrets.token_hex(16)) -- must be cryptographically
               # unguessable, unlike run-gate's other identifiers.
               "secrets",
               # resource: RG-57's bare-host daemon-absent path originally
               # The historical rejected implementation used
               # resource.getrusage(RUSAGE_CHILDREN); RW-43/B1 replaced it
               # with `os.wait4()` on the lane's own child
               # (exact per-child accounting, no import needed beyond
               # `os`, already allowed above) -- "resource" deliberately
               # NOT in this set any more: the import was removed.
               }
    allowed.add("hashlib")  # RG-47 config provenance fingerprint
    # collections: RG-84 (ff5786d66) imports `collections.abc.Callable` for
    # type annotations only; stdlib, no runtime dependency.
    allowed.add("collections")
    # select: RG-55's placement ready/continue barrier waits on the wrapper's
    # private readiness pipe without timing out a slow command's lane body.
    # grp: resolve host group identity for safe observer socket access.
    # importlib: read the installed wheel's SemVer distribution metadata.
    allowed.update({"copy", "contextlib", "dataclasses", "grp", "importlib",
                   "io", "select", "signal", "stat", "run_gate_admission"})
    assert set(imports) <= allowed, f"non-stdlib/unplanned imports: {imports}"


