        assay.mkdir(parents=True)
        for suffix in ("json", "txt"):
            (assay / f"campaign-unit.{suffix}").write_text("")
        (assay / "campaign-unit.exit").write_text("0 0\n")
        closeout = self._collect(tmp_path, monkeypatch, assay / "verdict-unit.json")
