def test_default_assay_state_root_preflight_distinguishes_missing_and_symlink(
        tmp_path, monkeypatch):
    repo = tmp_path / "repo"
    repo.mkdir()
    root = repo / ".run-gate"
    assert run_gate.default_assay_state_root_status(root) == ("creatable", None)
    outside = tmp_path / "outside"
    outside.mkdir()
    root.symlink_to(outside, target_is_directory=True)
    status, reason = run_gate.default_assay_state_root_status(root)
    assert status == "invalid" and "not a real directory" in reason
    root.unlink()
    blocked_parent = tmp_path / "not-a-directory"
    blocked_parent.write_text("file")
    status, reason = run_gate.default_assay_state_root_status(
        blocked_parent / ".run-gate")
    assert status == "invalid" and "parent" in reason

    absent_under_unknown_parent = tmp_path / "unknown-parent" / ".run-gate"
    monkeypatch.setattr(run_gate, "host_state_directory_status",
                        lambda _path: ("unknown", "parent access denied"))
    assert run_gate.default_assay_state_root_status(
        absent_under_unknown_parent) == ("unknown", "parent access denied")
    monkeypatch.setattr(run_gate, "host_state_directory_status",
                        lambda _path: ("unavailable", None))
    status, reason = run_gate.default_assay_state_root_status(
        absent_under_unknown_parent)
    assert status == "invalid" and "not a writable directory" in reason

    original_lstat = Path.lstat

    def inaccessible_root(path):
        if path == absent_under_unknown_parent:
            raise PermissionError("root access denied")
        return original_lstat(path)

    monkeypatch.setattr(Path, "lstat", inaccessible_root)
    status, reason = run_gate.default_assay_state_root_status(
        absent_under_unknown_parent)
    assert status == "unknown" and "root access denied" in reason


def test_source_backed_assay_inner_installs_selected_worktree_source():
    inner = run_gate.build_assay_inner(
        {"assay_lane": "x", "pins": {}}, Path("/proj"), Path("/repo"),
        worktree=Path("/tree"),
    )
    assert "pip install" in inner
    assert "--editable /tree/assay" in inner
    assert "importlib.machinery.PathFinder.find_spec" in inner
    # shlex.quote changes the literal quote characters around "assay"; pin
    # the selected resolver call without pinning that shell-encoding detail.
    assert "spec=importlib.util.find_spec" in inner
    assert "import assay" not in inner
    assert "assay/src/assay/__init__.py" in inner
    assert "/tree" in inner
    assert "not from the selected worktree source" in inner
    assert 'cd / && "$ASSAY_PYTHON" -I -m pip install' in inner
    assert '"$ASSAY_PYTHON" -I -c' in inner
    assert "PathFinder.find_spec" in inner
    assert "assay.__file__" not in inner
    assert '"$ASSAY_PYTHON" -I -m assay.cli run x' in inner
    assert inner.index("--editable /tree/assay") < inner.rindex("cd /proj")
    assert inner.rindex("cd /proj") < inner.index(
        "not from the selected worktree source")
    assert inner.index("rm -f -- .assay/verdict-x.json") < inner.index(
        "--editable /tree/assay")
    assert "assay-6." not in inner
    assert "sha256sum" not in inner


def test_changelog_uses_wheel_semver_and_preserves_removed_release_notes():
    changes = (RUN_GATE_DIR / "CHANGES.md").read_text()
    preserved = (RUN_GATE_DIR / "nyxloom-trove" / "reports" /
                 "CMRU-KI58-unreleased-notes-carry-forward-2026-10-13.md")
    notes = preserved.read_text()

    assert "SemVer from the installed wheel is the public tool identity" in changes
    assert "persisted `revision` fields are provenance only" in changes
    assert "## [23.10.0]" in changes
    assert "## [Unreleased]" in changes
    # CMRU requires the working section to stay empty until release; these
    # removed notes remain preserved verbatim for the upcoming versioned
    # section rather than being silently discarded.
    assert "RG-90, rev 60" in notes
    assert "RG-55/P5, rev 64" in notes
    assert "observer-only Unix socket" in notes
    assert "CP-11" in notes


def test_selftest_lane_uses_bind_mounted_pytest_scratch_root():
    """Keep pytest fixture repositories mount-visible in tester-unified.

    Tester images need not define a working directory, so the command first
    enters this project's directory. Pytest resolves its basetemp path, so a
    symlink to /tmp does not keep fixture paths short. Keep basetemp beneath
    this bind-mounted checkout for doctor/mountinfo tests; AF_UNIX tests use
    their own short /tmp fixture. Git's ceiling prevents temporary repositories
    from discovering the source checkout.
    """
    config = tomllib.loads((RUN_GATE_DIR / "run-gate.toml").read_text())
    argv = config["lanes"]["selftest"]["argv"]

    assert argv[:2] == ["bash", "-c"] and len(argv) == 3
    script = argv[2]
    assert script.startswith("cd {worktree}/run-gate-project && mkdir -p .run-gate/ && ")
    verify = 'verify-running --receipt "$RUN_GATE_RELEASE_WHEEL_RECEIPT"'
    scratch = "RUN_GATE_TMP=$(mktemp -d .run-gate/selftest.XXXXXX)"
    assert verify in script
    assert script.index(verify) < script.index(scratch)
    assert 'RUN_GATE_ABS="$(realpath "$RUN_GATE_TMP")"' in script
    assert 'GIT_CEILING_DIRECTORIES="$RUN_GATE_ABS"' in script
    assert '--basetemp "$RUN_GATE_ABS"' in script
    assert "trap 'status=$?" in script


