def _docker_argv_line(stdout: str) -> str:
    lines = [ln for ln in stdout.splitlines() if "docker argv:" in ln]
    assert len(lines) == 1, stdout
    return lines[0].split("docker argv:", 1)[1].strip()


class TestDryRun:
    def _proj(self, tmp_path):
        repo = make_repo(tmp_path)
        proj = make_project(repo, SIMPLE_LANE)
        return repo, proj

    def test_container_lane_dry_run_prints_identical_argv_runs_nothing(
            self, tmp_path, monkeypatch):
        """THE oracle: no `docker run`, and the printed argv is what a live
        run would use (container NAME normalized out — it embeds pid/epoch)."""
        repo, proj = self._proj(tmp_path)
        log = fake_docker(tmp_path, monkeypatch)

        live = run_tool(proj, "suite")
        assert live.returncode == 0, live.stderr
        live_line = _docker_argv_line(live.stdout)
        import re as _re
        def norm(line):  # name embeds pid/epoch; overlay dir is random per run
            line = _re.sub(r"--name \S+", "--name N", line)
            return _re.sub(r"run-gate-gitcfg-\w+", "run-gate-gitcfg-X", line)
        live_norm = norm(live_line)

        log.write_text("")
        dry = run_tool(proj, "suite", "--dry-run")
        assert dry.returncode == 0, dry.stderr
        assert docker_runs(log) == [], "dry-run must not start a container"
        dry_line = _docker_argv_line(dry.stdout)
        assert norm(dry_line) == live_norm
        assert "DRY RUN" in dry.stdout

    def test_profiled_container_dry_run_discloses_would_wait_without_start(
            self, tmp_path, monkeypatch, capsys):
        repo, proj = self._proj(tmp_path)
        log = fake_docker(tmp_path, monkeypatch)
        monkeypatch.setenv(run_gate.PROFILE_AMBIENT_ENV_VAR, "on")
        monkeypatch.chdir(proj)
        monkeypatch.setattr(sys, "argv", ['run-gate'])
        preflights = []

        def preflight(*args, **kwargs):
            preflights.append((args[6], kwargs.get("dry_run")))
            print("run-gate: admission: would wait — fixture", flush=True)
            return {"admission": {"state": "would-wait"}}

        monkeypatch.setattr(run_gate, "prepare_profile_start", preflight)
        assert run_gate.main(["suite", "--dry-run"]) == 0
        assert preflights == [("container", True)]
        assert "admission: would wait" in capsys.readouterr().out
        assert docker_runs(log) == []
        assert docker_execs(log) == []

