        exclude = repo / ".git" / "info" / "exclude"
        with exclude.open("a") as stream:
            stream.write("\n.assay/\n.run-gate/\n")
        monkeypatch.chdir(proj)
        monkeypatch.setattr(sys, "argv", ['run-gate'])
        monkeypatch.chdir(proj)
