        write_progress(w.path, candidate(40))
        w.clock.advance(100)
        assert w.watch.poll() is None
        assert "candidate 40/172" in capsys.readouterr().out
        w.path.unlink()
        w.clock.advance(100)
        assert w.watch.poll() is None
        assert "no longer readable — it was, at candidate 40/172" \
            in capsys.readouterr().out

