        clock.advance(299)
        psi[0] = 6.0
        assert watch.poll() is None
        clock.advance(600)
        assert watch.poll() is None
        psi[0] = 0.0
        assert watch.poll() is None
        clock.advance(1)
        stalled = watch.poll()
        assert stalled is not None
        assert "last event seen: baseline command progress" in stalled

