        record.update({"_started_monotonic": time.monotonic(), "dirty": False,
                       "git_operation": None, "verdict": "PASS"})

        result = run_gate._dispatch(["unit", "--allow-dirty"])
        run_gate.finish(result)

        assert result.verdict == "PASS"
